PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS admission_prospectuses (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), class_id TEXT NOT NULL REFERENCES classes(id), academic_year_id TEXT NOT NULL REFERENCES academic_years(id), content TEXT, document_url TEXT, document_name TEXT, document_type TEXT, document_size INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'PUBLISHED', 'UNPUBLISHED')), is_published INTEGER NOT NULL DEFAULT 0, published_at TEXT, published_by TEXT REFERENCES users(id), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL, UNIQUE(school_id, class_id, academic_year_id));
CREATE INDEX IF NOT EXISTS idx_admission_prospectus_published ON admission_prospectuses(school_id, class_id, academic_year_id, is_published);
